
// story.ts – Complete story with all 42 chapters
// All text fields use backticks, everything else uses single quotes

export type DialogueLine = {
  speaker: string;
  text: string;
  portrait?: string;
};

export type Achievement = string | {
  name: string;
  description?: string;
  condition?: string;
};

export type StoryNode = {
  id: string;
  title: string;
  type: 'dialogue' | 'combat';
  dialogues: DialogueLine[];
  description?: string;
  target?: string;
  objectives?: string[];
  achievements?: Achievement[];
  bossUnlockId?: string;
  forcedIdentity?: string;
  useDawnbreaker?: boolean;
  postBattleDialogues?: DialogueLine[];
};

export type StoryCollectible = {
  id: string;
  name: string;
  icon: string;
  description: string;
};

export type StoryChapter = {
  id: string;
  title: string;
  completed: boolean;
  nodes: StoryNode[];
  joinAllies?: string[];
  collectible?: StoryCollectible;
};

function sNode(id: string, title: string, dialogues: DialogueLine[], description: string) {
  return { id, title, type: 'dialogue' as const, dialogues, description };
}

function bNode(
  id: string,
  title: string,
  dialogues: DialogueLine[],
  description: string,
  target: string,
  objectives: string[],
  achievements: Achievement[],
  bossUnlockId?: string,
  forcedIdentity?: string,
  useDawnbreaker?: boolean,
  post?: DialogueLine[]
) {
  return {
    id,
    title,
    type: 'combat' as const,
    dialogues,
    description,
    target,
    objectives,
    achievements,
    bossUnlockId,
    forcedIdentity,
    useDawnbreaker,
    postBattleDialogues: post,
  };
}

function chapter(id: string, title: string, nodes: StoryNode[], collectible?: StoryCollectible, joinAllies?: string[]) {
  return { id, title, completed: false, nodes, joinAllies, collectible };
}

